function maxSubArray(nums) {
  let best = -Infinity;
  for (let i = 0; i < nums.length; i++) {
    let runningSum = 0;
    for (let j = i; j < nums.length; j++) {
      runningSum += nums[j];
      if (runningSum > best) best = runningSum;
    }
  }
  return best;
}

